cssCode:
.share-wrap {
  position: relative; width: 60px; height: 60px;
  display: flex; align-items: center; justify-content: center;
}
.share-btn {
  width: 60px; height: 60px; border-radius: 30px;
  background: #ff007f; color: #fff; font-size: 24px;
  border: none; cursor: pointer; z-index: 10;
  transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.3s;
  box-shadow: 0 10px 20px rgba(255,0,127,0.4);
}
.share-btn:active { transform: scale(0.9); }
.social-icons {
  position: absolute; display: flex; gap: 15px;
  opacity: 0; transform: translateX(0); pointer-events: none;
  transition: all 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.social-icon {
  width: 40px; height: 40px; background: #222; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: #00d2ff; font-weight: bold; font-family: sans-serif;
  border: 1px solid rgba(0,210,255,0.3);
}
.share-wrap.active .social-icons {
  opacity: 1; transform: translateX(110px); pointer-events: auto;
}
.share-wrap.active .share-btn {
  transform: translateX(-80px); background: #222; color: #ff007f; border: 1px solid #ff007f;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'share-wrap';

const btn = document.createElement('button');
btn.className = 'share-btn';
btn.innerText = '➦';

const iconsWrap = document.createElement('div');
iconsWrap.className = 'social-icons';

['f', 'X', 'in'].forEach(icon => {
  const i = document.createElement('div');
  i.className = 'social-icon';
  i.innerText = icon;
  iconsWrap.appendChild(i);
});

wrap.appendChild(iconsWrap);
wrap.appendChild(btn);
c.appendChild(wrap);

btn.addEventListener('click', () => {
  wrap.classList.toggle('active');
});
